package com.mushafi.qa;
import android.app.*;import android.content.*;import android.graphics.*;import android.service.notification.*;import com.mushafi.app.*;import java.lang.reflect.*;import android.os.*;
final class NotificationIconChecks {
 static void need(boolean b,String why)throws Exception{if(!b)throw new Exception(why);}
 static void check(Context c,Notification n)throws Exception{need(n.getSmallIcon()!=null&&n.getSmallIcon().getResId()==AppIdentity.notificationIcon(c),"OS small icon retained");need(n.getLargeIcon()==null&&n.largeIcon==null,"no duplicate app artwork");need(n.extras.get(Notification.EXTRA_LARGE_ICON)==null&&n.extras.get(Notification.EXTRA_LARGE_ICON_BIG)==null,"no recovered artwork extras");need(n.color==0xFFE6CF9A,"fixed gold accent");}
 static void run(Instrumentation i)throws Exception{Context c=i.getTargetContext();MainActivity main=(MainActivity)i.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PrayerSettings s=PrayerSettings.load(c);for(String kind:new String[]{"adhan","reminder","iqama"})check(c,PrayerScheduler.notification(c,s,"isha",kind,System.currentTimeMillis(),false,false,false));check(c,PrayerScheduler.notification(c,s,"isha","adhan",System.currentTimeMillis(),true,true,true));Field f=MainActivity.class.getDeclaredField("surahService");f.setAccessible(true);long until=System.currentTimeMillis()+15000;while(f.get(main)==null&&System.currentTimeMillis()<until)Thread.sleep(100);need(f.get(main)!=null,"media service bound");Method m=SurahPlaybackService.class.getDeclaredMethod("notification");m.setAccessible(true);Notification media=(Notification)m.invoke(f.get(main));need(media.getSmallIcon().getResId()==AppIdentity.notificationIcon(c),"media keeps official system icon");need(media.getLargeIcon()!=null,"media has reciter artwork");
 ReciterArtwork art=new ReciterArtwork();Bitmap previous=null;
 for(int reader:new int[]{7,133,6,2,3,1001,1002,1003,1004,1005}){Bitmap cover=art.forReader(c,reader);need(cover!=null&&cover.getWidth()==384&&cover.getHeight()==384,"bounded artwork for "+reader);need(art.forReader(c,reader)==cover,"artwork cache for "+reader);need(cover!=previous,"reader change refreshes artwork");previous=cover;}
 need(art.forReader(c,-1)==null,"unknown reader cannot reuse previous artwork");
 Object service=f.get(main);Field readerField=SurahPlaybackService.class.getDeclaredField("reader");readerField.setAccessible(true);int originalReader=readerField.getInt(service);Field sessionField=SurahPlaybackService.class.getDeclaredField("session");sessionField.setAccessible(true);Method update=SurahPlaybackService.class.getDeclaredMethod("updateSession");update.setAccessible(true);
 try{for(int reader:new int[]{7,133,6,2,3,1001,1002,1003,1004,1005}){readerField.setInt(service,reader);update.invoke(service);android.media.MediaMetadata metadata=((android.media.session.MediaSession)sessionField.get(service)).getController().getMetadata();need(metadata!=null,"media metadata exists");for(String key:new String[]{android.media.MediaMetadata.METADATA_KEY_ALBUM_ART,android.media.MediaMetadata.METADATA_KEY_ART,android.media.MediaMetadata.METADATA_KEY_DISPLAY_ICON})need(metadata.getBitmap(key)!=null,"media artwork key for "+reader);Notification current=(Notification)m.invoke(service);need(current.getLargeIcon()!=null,"reader cover in media notification "+reader);need(current.getSmallIcon().getResId()==AppIdentity.notificationIcon(c),"system identity retained for "+reader);}}finally{readerField.setInt(service,originalReader);update.invoke(service);}

 NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String channel="qa_icon_silent";NotificationChannel ch=new NotificationChannel(channel,"QA",NotificationManager.IMPORTANCE_LOW);ch.setSound(null,null);manager.createNotificationChannel(ch);PendingIntent open=PendingIntent.getActivity(c,7970,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Bitmap bitmap=Bitmap.createBitmap(32,32,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.GREEN);Notification old=new Notification.Builder(c,channel).setSmallIcon(AppIdentity.notificationIcon(c)).setLargeIcon(bitmap).setColor(AppIdentity.notificationColor(c)).setContentTitle("QA icon test").setContentText("content preserved").setContentIntent(open).addAction(android.R.drawable.ic_menu_close_clear_cancel,"QA action",open).build();try{old.extras.putString("mushafi.officialIconRevision","official-fixed-v1");old.extras.putParcelable(Notification.EXTRA_LARGE_ICON_BIG,bitmap);manager.notify(7971,media);manager.notify(7970,old);Thread.sleep(200);AppIdentity.normalizeNotifications(c);Thread.sleep(300);Notification clean=null;for(StatusBarNotification active:manager.getActiveNotifications())if(active.getId()==7970)clean=active.getNotification();need(clean!=null,"notification still present");check(c,clean);Notification retained=null;for(StatusBarNotification active:manager.getActiveNotifications())if(active.getId()==7971)retained=active.getNotification();need(retained!=null&&retained.getLargeIcon()!=null,"opening app preserves media portrait");need(retained.getSmallIcon().getResId()==AppIdentity.notificationIcon(c),"media identity unchanged");need(clean.extras.getCharSequence(Notification.EXTRA_TITLE).toString().equals("QA icon test"),"title preserved");need(clean.contentIntent.equals(open)&&clean.actions.length==1,"tap and actions preserved");need((clean.flags&Notification.FLAG_ONLY_ALERT_ONCE)!=0,"no repeat alert on cleanup");}finally{manager.cancel(7970);manager.cancel(7971);}
 }
}
